def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        use_count = {}

        def wrapper(*args, **kwargs):
            if args in cache:
                use_count[args] += 1
                return cache[args]
            else:
                result = func(*args, **kwargs)
                cache[args] = result
                use_count[args] = 1

                if len(cache) > maxsize:
                    for key, _ in sorted(use_count.items(), key=lambda x: x[1]):
                        del cache[key]
                        del use_count[key]
                        break

                return result

        return wrapper

    return decorator
