def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # sort the classes by their MRO (method resolution order), so that parents come before their children
    classes.sort(key=lambda x: x.mro())

    # create a set to store the unique classes
    unique_classes = set()

    # iterate over the sorted classes and add each one to the set
    for cls in classes:
        if cls not in unique_classes:
            unique_classes.add(cls)

    # return the unique classes as a list
    return list(unique_classes)

