def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    if not isinstance(prior, type(self)):
        raise ValueError("Prior version must be a InventoryValidator object")

    if prior == self:
        raise ValueError("Prior version cannot be the same object as the current version")

    for item in prior.items:
        if item not in self.items:
            raise ValueError("Prior version contains item not in the current version")

    for item in self.items:
        if item not in prior.items:
            raise ValueError("Current version contains item not in the prior version")

    for item in self.items:
        if item.quantity < prior.items[item].quantity:
            raise ValueError("Current version contains item with insufficient quantity")

    for item in prior.items:
