def deep_merge_nodes(nodes):
    result = []
    seen_keys = set()
    for key_value_pair in nodes:
        key, value = key_value_pair
        if key in seen_keys:
            # find the existing value with the same key and deep merge it
            for existing_key_value_pair in result:
                existing_key, existing_value = existing_key_value_pair
                if existing_key == key:
                    existing_value = deep_merge_nodes([(existing_key, existing_value), (key, value)])
                    break
            result.append((key, existing_value))
        else:
            result.append(key_value_pair)
            seen_keys.add(key)
    return result

