            raise ValueError(f"Value of argument '{arg}' is longer than the length specified ({self.length}).")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.
    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices and arg_value not in self.choices[arg_name]:
            raise ValueError(f"Invalid choice '{arg_value}' for argument '{arg_name}', must be one of {', '.join(self.choices[arg_name])}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if not (self.argument_min <= arg <= self.argument_max):
            raise ValueError("The value of argument {} is not within the acceptable range of {} to {}".format(arg, self.argument_min, self.argument_max))

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control and nested.

    Control arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: The collected list of args.
    :return: (dict, dict): Nested and control args as flat dicts
        (control_args, nested_args).
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for k, v in args.items():
        if k in self.CONTROL_ARGS:
            control_args[k] = v
        elif k in self.NESTED_ARGS:
            nested_args[k] = v
        elif k in self.CUSTOM_ARGS:
            custom_args[k] = v
        else:
            raise KeyError(f"Invalid argument found: {k}")

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars:
        for extra_var in extra_vars:
            if extra_var not in vars_dict:
                vars_dict[extra_var] = None

def remove_extra_vars(vars_dict, extra_vars=None):
    """Remove ``extra-vars`` from ``vars_dict``

    :param vars_dict: Dictionary to remove extra-vars from
    :param extra_vars: List of extra-vars
    """
    if extra_vars:
        for extra_var in extra_vars:
            if extra_var in vars_dict:
                del vars_dict[extra_var]

def update_extra_vars(vars_dict, extra_vars=None):
    """Update ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to update extra-vars in
    :param extra_vars: List of extra-vars
    """
    if extra_vars:
        for extra_var in extra_vars:
            if extra_var in vars_dict:
                if isinstance(vars_dict[extra_var], list):
                    vars_dict[extra_var].extend(extra_vars[extra_var])
                elif isinstance(vars_dict[extra_var], dict):
                    vars_dict[extra_var].update(extra_vars[extra_var])
                else:
                    vars_dict[extra_var] = extra_vars[extra_var]

def is_extra_var(var_name):
    """Check if ``var_name`` is an extra-var

    :param var_name: Name of the variable (string)
    :return: ``True`` if ``var_name`` starts with the extra-var prefix, ``False`` otherwise
    """
    return var_name.startswith('extra_var_')

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):

    if verbose is not None:
        args = ['-v'] * int(verbose)

    # If extra_vars are provided, expand any environment variables found in
    # their values and then transform the dictionary to a list of key=value
    # strings.
    if extra_vars:
        for key, value in extra_vars.items():
            value = os.path.expandvars(value)
            args.append(f"{key}={value}")

    # If Ansible args are provided, prepend and dash to each and append to the
    # args list.
    if ansible_args:
        for arg in ansible_args:
            args.append(f"-{arg}")

    # Finally, append the playbook path and run the playbook.
    args.append(playbook_path)
    completed_process = run_async_wrapper(
        SubprocessManager.communicate_runner(ir_workspace, ir_plugin, *args, tty=True, input_array=True)
    )

    # Return the output, with and without color, from the
    # completed process.
    return (completed_process.stdout.strip(), completed_process.stdout_text)

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    command = ["ansible-playbook"] + cli_args
    for key, value in vars_dict.items():
        command.append("-e")
        command.append("%s=%s" % (key, value))
    try:
        result = subprocess.run(command, cwd=ir_workspace.workspace_dir, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output = result.stdout.decode("utf-8")
        error = result.stderr.decode("utf-8")
        return {"output": output, "error": error, "return_code": result.returncode}
    except subprocess.CalledProcessError as e:
        error = e.stderr.decode("utf-8")
        return {"error": error, "return_code": e.returncode}
    except OSError as e:
        return {"error": "Failed to run command: %s" % str(e), "return_code": 1}

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import yaml
    from collections import defaultdict

    flatten_dict = defaultdict(dict)

    plugin_spec_path = os.path.join(plugin_dir, 'plugin.yaml')
    with open(plugin_spec_path, 'r') as f:
        plugin_spec = yaml.safe_load(f)

    for prop_name, prop_spec in plugin_spec.items():
        if prop_name == 'name' or prop_name == 'version':
            continue

        if not isinstance(prop_spec, dict) or 'type' not in prop_spec:
            continue

        prop_type = prop_spec['type']
        if prop_type == 'string':
            flatten_dict[prop_name] = prop_spec.get('default', '')
        elif prop_type == 'number':
            flatten_dict[prop_name] = prop_spec.get('default', 0)
        elif prop_type == 'boolean':
            flatten_dict[prop_name] = prop_spec.get('default', False)
        else:
            continue

    return flatten_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.getenv("CONFIG_PATH"):
        os.environ["CONFIG_PATH"] = "config.yml"

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
